// Approved review revision: per-document AI consent, user-owned care items and shared facts.
const careExamples=[{id:'sleep',name:'睡眠',topic:'sleep',icon:'moon'},{id:'diet',name:'饮食',topic:'food',icon:'coffee'},{id:'activity',name:'活动',topic:'movement',icon:'today'}];
const cueWords=['高数','英语','错题','阅读','历史书','跑步','慢跑','散步','力量训练','健身','拉伸','午睡','睡眠','饮食','早餐','三餐','喝水','远眺','部署','交换机','绘画','画画','朋友','感谢','音乐'];
function ensureReviewV2(){
 if(!state.careItems)state.careItems=careExamples.map(x=>({...x,schedule:'daily',weekdays:[],enabled:true}));
 state.careEntries ||= {};state.ignoredCareTopics ||= [];state.actionFacts ||= {};
 state.records.forEach(r=>{
  if(r.aiConsent===undefined)r.aiConsent=!!(r.suggestion||r.confirmedSnapshot||r.sessions?.length||r.analysisIntent==='now');
  if(r.aiConsent)r.aiConsentVersion ??= r.version;
  if(r.settled&&!r.reused&&!r.sameFactAs&&!r.canonicalHandled){const changes=legacyAttributeChanges(r);if(changes.length){const id=r.factId||r.id;state.actionFacts[id] ||= {id,sourceRecordId:r.id,day:r.contentDay,text:r.confirmedSnapshot?.text||r.text,attribute:r.confirmedSnapshot?.attribute||r.attribute||r.suggestion?.attribute,award:r.award||0,settled:true};r.factId=id;r.canonicalHandled=true}}
 });
 Object.values(state.actionFacts).forEach(f=>{f.fingerprint ||= factFingerprint(f.text)});
}
function careTopic(name){return /睡|午休|小憩/.test(name)?'sleep':/饮食|吃饭|三餐|早餐/.test(name)?'food':/活动|运动|跑|散步|训练/.test(name)?'movement':name}
function careDue(item,day=state.day){return item.enabled!==false&&(item.schedule==='daily'||item.schedule==='weekly'&&(item.weekdays||[]).includes(weekday(day)))}
function careEntry(item,day=state.day){return state.careEntries[day+'@'+item.id]}
function careNote(item){const e=careEntry(item),r=state.records.find(r=>r.id===e?.recordId);return e?.status==='skipped'?'今天先跳过':r?r.text:state.care[state.day+'@'+item.name]||'还没记录，不代表没有做'}
function careCard(){const items=state.careItems.filter(i=>careDue(i));if(!state.careVisible||!items.length)return '';return `<section class="card care-card"><div class="section-title"><h3>也记得照顾自己</h3><a href="#care-settings" class="text-button">管理项目</a></div>${items.map(item=>`<div class="mini-item"><span class="icon-box">${icon(item.icon||'today')}</span><div><strong>${esc(item.name)}</strong><p>${esc(careNote(item))}</p><div class="row wrap"><button class="text-button" data-care="record" data-id="${item.id}">${careEntry(item)?.recordId?'查看 / 修改':'简单记一下'}</button><button class="text-button" data-care="skip" data-id="${item.id}">今天跳过</button></div></div></div>`).join('')}<p class="care-rest">项目和数量由你决定。基本休息一直自由。</p></section>`}
function careSettingsPage(){return back('my')+heading('照顾自己，由你来定','想关注什么就留下什么，数量不限，也可以一项都不放。')+`<section class="card mb"><div class="row between"><div><h2>在首页显示</h2><p class="small muted">全部关闭或没有当天安排时，首页不显示这块。</p></div><button class="switch ${state.careVisible?'on':''}" data-care="toggle" role="switch" aria-checked="${state.careVisible}" aria-label="首页显示照顾自己"></button></div></section><section class="card"><div class="section-title"><h2>我的项目 <span class="small muted">${state.careItems.length} 项</span></h2><button class="btn soft" data-care="add">＋ 添加项目</button></div>${state.careItems.map((item,i)=>`<div class="list-row"><div><h3>${esc(item.name)}</h3><small>${item.schedule==='daily'?'每天':item.schedule==='weekly'?'每周 '+(item.weekdays||[]).map(d=>'日一二三四五六'[d]).join('、'):'自行安排'}${item.enabled===false?' · 已停用':''}</small><div class="row wrap"><button class="text-button" data-care="record" data-id="${item.id}">记一下</button><button class="text-button" data-care="edit" data-id="${item.id}">编辑</button><button class="text-button" data-care="move" data-id="${item.id}" data-step="-1" ${i===0?'disabled':''}>上移</button><button class="text-button" data-care="move" data-id="${item.id}" data-step="1" ${i===state.careItems.length-1?'disabled':''}>下移</button><button class="text-button danger-text" data-care="delete" data-id="${item.id}">移除</button></div></div></div>`).join('')||'<p class="empty">还没有项目。保持空白也可以，系统不会因此追问你睡眠或运动。</p>'}</section><details class="card mt"><summary>可选示例与 AI 建议</summary><p class="small muted mt">这些是候选，不会自动加到你的首页。AI 建议也需要你自己决定。</p><div class="row wrap mt">${['睡眠','饮食','活动','喝水','用眼休息','阅读','午睡'].map(name=>`<button class="btn compact" data-care="example" data-name="${name}">${name}</button>`).join('')}</div><button class="text-button mt" data-care="suggest">看看近期的可选建议（模拟）</button><div id="care-suggestions"></div></details>`}
function editCare(id,name=''){const item=state.careItems.find(i=>i.id===id);openDialog(item?'编辑项目':'添加自己关注的项目',`<label class="field">项目名称<input id="care-name" maxlength="80" placeholder="例如：喝水、用眼休息、画画" value="${esc(item?.name||name)}"></label><label class="field">什么时候出现？<select id="care-schedule"><option value="daily" ${!item||item.schedule==='daily'?'selected':''}>每天</option><option value="weekly" ${item?.schedule==='weekly'?'selected':''}>指定星期</option><option value="manual" ${item?.schedule==='manual'?'selected':''}>自行安排，只在管理页保留</option></select></label><div id="care-weekdays" ${item?.schedule==='weekly'?'':'hidden'}><span class="small">每周哪些天？</span><div class="weekday-options">${[1,2,3,4,5,6,0].map(d=>`<label class="check-option"><input name="care-weekday" type="checkbox" value="${d}" ${(item?.weekdays||[]).includes(d)?'checked':''}>周${'日一二三四五六'[d]}</label>`).join('')}</div></div><label class="check-option"><input id="care-enabled" type="checkbox" ${item?.enabled===false?'':'checked'}>启用这个项目</label>`,()=>{const value=$('#care-name').value.trim(),schedule=$('#care-schedule').value,weekdays=[...document.querySelectorAll('[name=care-weekday]:checked')].map(e=>Number(e.value));if(!value)return failDialog('请写下项目名称。');if(state.careItems.some(x=>x.id!==id&&x.name===value))return failDialog('已经有同名项目，可以直接编辑。');if(schedule==='weekly'&&!weekdays.length)return failDialog('至少选择一个星期。');const data={name:value,topic:careTopic(value),schedule,weekdays,enabled:$('#care-enabled').checked};if(item)Object.assign(item,data);else state.careItems.push({id:uid(),icon:'today',...data});state.ignoredCareTopics=state.ignoredCareTopics.filter(t=>t!==data.topic);save();closeDialog();render()},'保存项目')}
function careRecordDialog(id){const item=state.careItems.find(i=>i.id===id);if(!item)return;const entry=careEntry(item),r=state.records.find(r=>r.id===entry?.recordId);openDialog('记一下'+item.name,`<label class="field">简单说说<textarea id="care-record-text" placeholder="做了什么，感觉怎么样？">${esc(r?.text||state.care[state.day+'@'+item.name]||'')}</textarea></label><label class="field">保存方式<select id="care-analysis-mode"><option value="private" ${!r?.aiConsent?'selected':''}>只保存，不交给 AI</option><option value="now" ${r?.aiConsent?'selected':''}>保存并分析</option></select></label><p class="small muted">记录保留在手账中。分析后先看属性和金币建议，确认才入账。</p>`,()=>{const text=$('#care-record-text').value.trim(),allowed=$('#care-analysis-mode').value==='now';if(!text)return failDialog('写一句想留下的内容，或者关闭后今天先跳过。');let record=r;if(record){if(record.text!==text){(record.revisions ||= []).push({version:record.version,text:record.text});record.text=text;record.version++;if(!record.settled){delete record.suggestion;delete record.clarify}}}else record=addRecord(text,'event',state.day,{source:'care',careItemId:item.id,careItemName:item.name,version:1,sessions:[]});setConsent(record,allowed);state.careEntries[state.day+'@'+item.id]={status:'saved',recordId:record.id};state.activeRecord=record.id;save();closeDialog();if(allowed){go('record');beginAnalysis(record)}else{render();toast('已保存，不参与 AI 分析。')}},'保存记录')}
function setConsent(r,allowed){r.aiConsent=allowed;r.aiConsentVersion=allowed?r.version:null;r.analysisIntent=allowed?'now':'private';if(!allowed){r.analysisToken=null;if(!r.settled){delete r.suggestion;r.analysisStatus='idle'}if(r.diaryAnalysis?.status==='ready')r.diaryAnalysis.status='paused'}}
function allowedRecords(r){return state.records.filter(x=>x.id!==r.id&&x.aiConsent===true&&x.contentDay===r.contentDay&&!x.revoked)}
function analysisPayload(r){if(!r.aiConsent)return null;return {current:{id:r.id,text:r.text,supplement:r.supplement||'',version:r.version},otherRecords:allowedRecords(r).map(x=>({id:x.id,text:x.text,settled:!!x.settled})),careTopics:state.careItems.filter(i=>careDue(i,r.contentDay)&&!state.ignoredCareTopics.includes(i.topic)).map(i=>i.name)}}
function consentDialog(r,after){openDialog('开启本篇分析？',`<p>只在你确认后，才允许分析这篇${r.kind==='diary'?'日记':'记录'}及你允许分析的当天记录。只保存的其他正文不会加入上下文。</p><p class="small muted">AI 辅助回顾仍由你另行点击，不会自动开始问答。</p>`,()=>{setConsent(r,true);save();closeDialog();after()},'允许分析本篇')}
function contextForDiary(r){if(!r.aiConsent)return '';return [r.text,...allowedRecords(r).map(x=>x.text),...r.sessions.flatMap(s=>s.turns.map(t=>t.answer||''))].join(' ')}
function reviewCandidates(r){if(!r.aiConsent)return [];const context=contextForDiary(r),used=new Set(r.sessions.flatMap(s=>s.turns.map(t=>t.topic))),questions=[];if(/沮丧|着急|难过|烦|疲惫|不开心|挫折/.test(context)&&!/支持|轻松|感谢|鼓励/.test(context)&&!used.has('support'))questions.push({topic:'support',text:'除了已经记下的困难，今天有没有一个让你稍微轻松，或感觉被支持的片段？没有也没关系。'});for(const item of state.careItems.filter(i=>careDue(i,r.contentDay))){const topic=item.topic;if(used.has(topic)||state.ignoredCareTopics.includes(topic)||careEntry(item,r.contentDay))continue;const planCovered=state.plans.some(p=>state.outcomes[p.id+'@'+r.contentDay]&&careTopic(p.title)===topic);const covered=planCovered|| (topic==='sleep'?/睡眠|睡了|起床|午睡/.test(context):topic==='food'?/饮食|吃饭|三餐|早餐|午餐|晚餐/.test(context):topic==='movement'?/跑步|运动|散步|训练|活动|健身/.test(context):context.includes(item.name));if(!covered)questions.push({topic,text:`关于你关注的「${item.name}」，今天有没有想补充的一句话？可以跳过。`})}return questions}
function suggestRecord(r){const text=r.text+' '+(r.supplement||''),study=/学习|高数|英语|复习|错题|阅读|历史书|解题/.test(text),sport=/跑步|慢跑|训练|运动|健身|拉伸/.test(text),rest=/午睡|远眺|休息|睡眠|睡了|三餐|早餐|饮食|喝水/.test(text);if(text.trim().length<6||!/完成|整理|练习|训练|跑步|读|学习|复习|散步|午睡|远眺|做了|写了|部署|解决|睡|吃|三餐|喝|画|休息|早餐/.test(text)){r.clarify='关于这件事，你具体做了什么，或有什么进展、感受？简单补充一句即可。';delete r.suggestion;return}ensureGoals();const plan=state.plans.find(p=>p.id===r.planId),goal=state.goals.find(g=>g.id===plan?.goalId)||[...state.goals].sort((a,b)=>Number(b.main)-Number(a.main)).find(g=>(study&&/考研|英语|学习|阅读|考试/.test(g.title+' '+g.note))||(sport&&/跑|运动|训练|健身/.test(g.title+' '+g.note)));const minutes=Number(text.match(/(\d+)\s*分钟/)?.[1]||0),grade=/通过考试|完成项目|发布作品|重要突破/.test(text)?2:rest&&!study&&!sport||/几分钟|一小步|短暂/.test(text)?0:1,dimension=study?'智力':sport?'体能':rest?'健康':/画|创作|设计/.test(text)?'创造力':'规划力',delta=Math.min(.8,Math.max(.1,[.15,.35,.6][grade]+(minutes>=60?.1:minutes>=20?.05:0)));r.suggestion={grade,goalId:goal?.id||'',main:!!goal?.main,holiday:state.scenario==='holiday'&&study,attribute:dimension+' +'+Number(delta.toFixed(2)),reason:'根据当前原文中的实际行动、投入线索和成果给出示例建议；与本人目标相关时仅增加主线金币。'};delete r.clarify}
function factTokens(text){let normalized=text.replace(/慢跑/g,'跑步').replace(/错题原因|错题笔记/g,'错题');return cueWords.filter(w=>normalized.includes(w))}
// Duplicate identity is checked locally against the historical ledger. No private body is added to an AI payload.
function factFingerprint(text){const normalized=text.replace(/[\s。；;，,！!？?]/g,'');let hash=2166136261;for(const char of normalized){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return {digest:(hash>>>0).toString(16),cues:factTokens(text)}}
function factMatch(text,fact){const a=factFingerprint(text),b=fact.fingerprint||factFingerprint(fact.text),same=a.cues.filter(x=>b.cues.includes(x)),strong=same.filter(x=>!['阅读','饮食','朋友'].includes(x));return a.digest===b.digest||same.length>=2||strong.length>=1&&/那次|已经记|白天|同一次|刚才/.test(text)}
function eligibleFacts(r){return Object.values(state.actionFacts).filter(f=>f.settled&&f.day===r.contentDay&&state.records.some(x=>x.id===f.sourceRecordId&&!x.revoked))}
function crossSourceMatches(r){return findFactMatches(r,r.text).filter(f=>f.sourceRecordId!==r.id&&(r.source==='care'||state.records.find(x=>x.id===f.sourceRecordId)?.kind==='diary'||state.records.find(x=>x.id===f.sourceRecordId)?.source==='care'))}

function findFactMatches(r,text){return eligibleFacts(r).filter(f=>factMatch(text,f))}
function beginAnalysis(r){if(!r||r.settled||r.revoked)return;if(!r.aiConsent){consentDialog(r,()=>beginAnalysis(r));return}if(state.model.source==='off'){openDialog('AI 当前已关闭','<p>原文和本篇选择已保存。配置模型后再分析，不会退回自动发奖。</p>',()=>{closeDialog();go('models')},'查看模型设置');return}const mode=!['demo-chat-model','example-chat'].includes(state.model.model)?'failed':$('#analysis-demo-result')?.value||'ready',token=uid();r.analysisStatus='queued';r.analysisToken=token;r.lastPayload=analysisPayload(r);save();render();setTimeout(()=>{if(r.analysisToken!==token||!r.aiConsent||r.revoked)return;if(mode==='failed'){r.analysisStatus='failed';delete r.suggestion}else if(mode==='needsInput'){delete r.suggestion;r.clarify='这件事的实际投入或结果是什么？可以补充与它相关的信息。';r.analysisStatus='needsInput'}else{suggestRecord(r);{const matches=r.forceSeparateFact?[]:crossSourceMatches(r);r.relatedFact=matches.length===1?matches[0].id:null}r.analysisStatus=r.suggestion?'ready':'needsInput'}save();if(state.route==='record'&&state.activeRecord===r.id)render()},650)}
function rewardView(r){const linked=state.actionFacts[r.relatedFact];if(linked?.settled)return `<p class="quote">这条记录可能对应已经入账的同一次行动。</p><p>${esc(linked.text)}</p><p class="note mt">确认是同一次时，本次新增属性 0、金币 0。两份原文都保留。</p><div class="row wrap mt"><button class="btn primary" data-review="confirm-event">确认同一次，不重复入账</button><button class="btn" data-review="separate-event">不是同一次行动</button></div>`;return legacyRewardView(r)+`<details><summary>本次分析使用的内容</summary><div class="body">${esc(JSON.stringify(r.lastPayload||analysisPayload(r),null,2))}</div></details>`}
function attributeChanges(r){if(r.revoked||r.reused||r.sameFactAs)return [];if(r.canonicalHandled)return Object.values(state.actionFacts).filter(f=>f.sourceRecordId===r.id&&f.settled&&!f.revoked).flatMap(f=>{const name=dimensions.find(n=>(f.attribute||'').startsWith(n)),num=(f.attribute||'').match(/[+-]\s*\d+(?:\.\d+)?/);return name&&num?[{name,delta:Number(num[0].replace(/\s/g,''))}]:[]});return legacyAttributeChanges(r)}
function confirmEvent(r){if(!r.aiConsent||!r.suggestion||r.settled)return;if(!state.profile.built)return toast('先选择游戏起点，再确认奖励。');if(!r.relatedFact&&!r.forceSeparateFact){const matches=crossSourceMatches(r);if(matches.length===1){r.relatedFact=matches[0].id;save();render();return toast('相关行动刚刚入账，请核对是不是同一次。')}}const linked=state.actionFacts[r.relatedFact];if(linked?.settled){r.sameFactAs=linked.sourceRecordId;r.reused=true;r.settled=true;r.award=0;r.factId=linked.id;r.confirmedSnapshot={text:r.text,attribute:'共享已有入账',version:r.version};save();render();return}const id=r.factId||r.id,c=calculation(r);if(!state.actionFacts[id]?.settled){ledger(c.total,'有效行动 · '+r.text.slice(0,24),'fact:'+id,'行动');state.actionFacts[id]={id,sourceRecordId:r.id,day:r.contentDay,text:r.text,attribute:r.suggestion.attribute,award:c.total,settled:true};}r.factId=id;r.settled=true;r.canonicalHandled=true;r.award=state.actionFacts[id].award;r.attribute=r.suggestion.attribute;r.settledDay=state.day;r.confirmedSnapshot={text:r.text,supplement:r.supplement||'',attribute:r.suggestion.attribute,version:r.version,goalId:r.suggestion.goalId};save();render()}
function diaryRecordCurrent(){return state.records.find(x=>x.id===state.diaryId)||diaryRecord()}
function analyzeDiary(r){if(!r?.aiConsent)return;if(state.model.source==='off'){toast('AI 已关闭，日记已保存，可以稍后配置再分析。');return}if(!['demo-chat-model','example-chat'].includes(state.model.model)){r.diaryAnalysis={status:'failed',version:r.version};save();render();return}const pieces=r.text.split(/[。；;\n]+|(?=另外|晚上|下午|上午)/).map(x=>x.trim()).filter(Boolean),items=[],seen=new Set();for(const text of pieces){const matches=findFactMatches(r,text);if(matches.length){for(const f of matches){if(seen.has(f.id))continue;seen.add(f.id);items.push({id:uid(),text,kind:'linked',factId:f.id,suggestion:null})}}else{const temp={text,kind:'diary'};suggestRecord(temp);items.push({id:uid(),text,kind:temp.suggestion?'new':'feedback',factId:uid(),suggestion:temp.suggestion||null})}}r.diaryAnalysis={status:'ready',version:r.version,items,payload:analysisPayload(r),feedback:'原文已保留。重复的白天行动只作回顾，新增事实单独提出建议；纯感受可以留作理解和回应，不强行凑奖励。'};save();render()}
function diaryAnalysisHTML(r){const a=r.diaryAnalysis;if(!a)return '<button class="btn primary mt" data-review="analyze-diary">分析这篇日记（模拟）</button>';if(a.status==='failed')return '<p class="error">模拟分析失败，原文保留。请核对模型后重试。</p><button class="btn" data-review="analyze-diary">重试分析</button>';if(a.version!==r.version)return '<p class="note mt">原文已经更新，旧结果保留为历史，重新分析后再核对。</p><button class="btn mt" data-review="analyze-diary">分析更新后的内容</button>';return `<p class="quote">${esc(a.feedback||'结果已保留。')}</p>${a.items.map(item=>{const f=state.actionFacts[item.factId],calc=item.suggestion?calculation({suggestion:item.suggestion}):null;return `<div class="diary-fact"><div class="row between wrap"><strong>${item.kind==='linked'?'与已有行动相同':item.kind==='new'?'新增事实建议':'仅作回顾反馈'}</strong><span class="tag ${item.kind==='linked'?'':'blue'}">${item.kind==='linked'?'本次不重复奖励':item.kind==='new'&&a.status!=='confirmed'?'待你确认':a.status==='confirmed'?'已核对':'不强行加点'}</span></div><p class="small mt">${esc(item.text)}</p>${item.kind==='linked'?`<p class="small muted">对应：${esc(f?.text||'历史来源')} · 本次新增 0 币、0 属性</p><button class="text-button" data-review="separate-diary-fact" data-id="${item.id}" ${a.status==='confirmed'?'disabled':''}>关联不对？这是另一件事</button>`:calc?`<p class="small muted">${esc(item.suggestion.attribute)} · 基础 ${calc.base}＋主线 ${calc.bonus}${calc.holiday?'＋节日 '+calc.holiday:''} 币${a.status==='confirmed'?'，实际入账见流水':'（仍受当日总上限约束）'}</p>`:''}</div>`}).join('')}${a.status!=='confirmed'?'<button class="btn primary mt" data-review="confirm-diary">核对并确认新增建议入账</button>':'<p class="reward-strip">本轮已核对，不会再次发奖。日记和事件记录仍分别保留。</p>'}<details><summary>查看本次允许分析的内容</summary><pre class="payload-preview">${esc(JSON.stringify(a.payload,null,2))}</pre></details>`}
function diaryPage(){const r=diaryRecordCurrent(),key=r?'diary-record@'+r.id:'diary@'+state.day,active=r?.sessions.find(s=>s.state==='active');return back('handbook')+heading('晚间日记','先由你决定是否分析。原文、引导、回答和分析分别保留。')+`<div class="two-col"><div class="stack"><section class="card"><div class="section-title"><h2>我写下的日记</h2><span class="tag ${r?'green':''}">${r?'已保存 · v'+r.version:'本机草稿'}</span></div><textarea id="diary-text" data-draft="${key}" style="min-height:210px">${esc(state.drafts[key]??r?.text??'')}</textarea><label class="field">保存方式<select id="diary-analysis-mode"><option value="private" ${!r?.aiConsent?'selected':''}>只保存，不交给 AI</option><option value="now" ${r?.aiConsent?'selected':''}>保存并分析</option></select></label><div class="row between wrap mt"><span class="small muted">${r?'首次保存日 '+r.savedDay:'保存后计入日记天数'}</span><button class="btn primary" data-full="save-diary">保存日记</button></div>${!r?.aiConsent?'<p class="daily-note">只保存时，正文不参与 AI 分析或后续回顾上下文；记录天数照常累计。</p>':''}</section>${r?.aiConsent?`<section class="card"><div class="section-title"><h2>这篇日记的分析</h2><span class="tag blue">先核对白天事实</span></div>${diaryAnalysisHTML(r)}</section><section class="card"><div class="section-title"><h2>可选：AI 辅助回顾</h2><span class="tag">你想继续时再开始</span></div><p class="small muted">避开已记内容、已跳过和你不关注的项目。问题、回答和分析不会混入原文。</p>${r.sessions.map(s=>diarySessionHTML(r,s)).join('')}${!active?`<button class="btn soft mt" data-full="start-review">${r.sessions.length?'再回顾一下':'帮我回顾一下'}</button>`:''}</section>`:r?`<section class="card private-summary"><p class="small muted">这篇仅保存，不参与 AI。以后改变想法，可以主动开启本篇分析。</p><button class="text-button" data-review="enable-diary">开启本篇分析</button>${r.sessions.length?`<details><summary>历史辅助记录（仍保留）</summary>${r.sessions.map(s=>diarySessionHTML(r,{...s,state:'finished',turns:s.turns.map(t=>({...t,state:t.state==='asked'?'skipped':t.state}))})).join('')}</details>`:''}</section>`:''}</div><aside class="card"><h3>当天已经记录的</h3>${state.records.filter(x=>x.id!==r?.id&&x.contentDay===(r?.contentDay||state.day)&&!x.revoked).map(recordRow).join('')||'<p class="empty">当天的事件和生活记录会在这里保留，不必再抄一遍。</p>'}<p class="small muted mt">这里是你自己的记录预览；只保存的正文不会因此进入 AI 上下文。</p></aside></div>`}
function saveFullDiary(){const text=$('#diary-text').value.trim(),allowed=$('#diary-analysis-mode').value==='now';if(!text)return toast('先写一点想留下的内容。');let r=diaryRecordCurrent();if(r){if(r.text!==text){(r.revisions ||= []).push({text:r.text,version:r.version});if(r.diaryAnalysis)(r.analysisHistory ||= []).push(r.diaryAnalysis);r.text=text;r.version++;r.diaryAnalysis=null}}else r=addRecord(text,'diary',state.day,{version:1,sessions:[]});setConsent(r,allowed);state.diaryId=r.id;delete state.drafts['diary@'+state.day];delete state.drafts['diary-record@'+r.id];save();if(allowed)analyzeDiary(r);else{render();toast('日记已保存，不参与 AI。')}}
function confirmDiary(r){const a=r.diaryAnalysis;if(!r.aiConsent||!a||a.status==='confirmed')return;if(!state.profile.built)return toast('先选择游戏起点，再确认奖励。');if(a.version!==r.version)return toast('原文已更新，请重新分析。');let changed=false;for(const item of a.items.filter(x=>x.kind==='new'&&!x.forceSeparate)){const match=findFactMatches(r,item.text)[0];if(match){item.kind='linked';item.factId=match.id;item.suggestion=null;changed=true}}if(changed){save();render();return toast('有相关行动刚刚入账，预览已更新，请再核对一次。')}let total=0;for(const item of a.items.filter(x=>x.kind==='new')){const id=item.factId;if(state.actionFacts[id]?.settled)continue;const prior=!item.forceSeparate&&findFactMatches(r,item.text)[0];if(prior){item.kind='linked';item.factId=prior.id;item.suggestion=null;continue}const c=calculation({suggestion:item.suggestion});ledger(c.total,'日记新增事实 · '+item.text.slice(0,24),'fact:'+id,'行动');state.actionFacts[id]={id,sourceRecordId:r.id,day:r.contentDay,text:item.text,attribute:item.suggestion.attribute,award:c.total,settled:true};total+=c.total}a.status='confirmed';r.canonicalHandled=true;r.award=(r.award||0)+total;r.settled=true;r.settledDay=state.day;r.attribute=attributeChanges(r).map(x=>x.name+' +'+x.delta).join('、');save();render()}
function anchorsPage(){return back('my')+heading('AI 如何判断','你描述事实，AI 提出建议；不需要自己设定每次加多少点。')+`<section class="card"><h2>看事实，不套固定加点表</h2><p class="quote">结合实际行动、投入、成果、个人基线和近期情况提出属性及金币建议。你可以纠正事实、目标关联或补充信息。</p><div class="guide-links">${[['① 保存原文','可选择只保存，不交给 AI。'],['② 根据事实建议','分析只使用你授权的正文与相关记录。'],['③ 核对已有入账','同一次行动出现在清单、事件和日记里，奖励只计一次。'],['④ 你确认后入账','系统核验金币规则、上限和重复操作；不让 AI 直接改账。']].map(([n,d])=>`<div class="principle"><h3>${n}</h3><p class="small muted">${d}</p></div>`).join('')}</div><p class="note">已确认的金币试用档位作为内部规则，用户不手选成果档，也不维护“学习固定加 0.4”。本 Demo 仍是有限规则模拟，正式版由所选模型分析并经系统校验。</p><a href="#history" class="text-button mt">查看自己的实际入账依据 →</a></section>`}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-care],[data-review]'),legacy=event.target.closest('[data-full],[data-action]');
 if(!b){
  if(legacy?.dataset.full==='save-event'){event.preventDefault();event.stopImmediatePropagation();const text=$('#event-text').value.trim(),day=$('#content-day').value,allowed=$('#analysis-intent').value==='now';if(!text)return toast('先写一点想留下的内容。');if(!day||day>state.day)return toast('请选择今天或更早的日期。');const r=addRecord(text,'event',day,{version:1,sessions:[]});setConsent(r,allowed);delete state.drafts['event@'+state.day];state.activeRecord=r.id;save();if(allowed){go('record');beginAnalysis(r)}else{render();toast('原文已保存，不参与 AI。')}return}
  if(legacy?.dataset.action==='confirm-reward'){event.preventDefault();event.stopImmediatePropagation();confirmEvent(state.records.find(r=>r.id===state.activeRecord));return}
  if(legacy?.dataset.full==='start-review'){const r=diaryRecordCurrent();if(!r?.aiConsent){event.stopImmediatePropagation();return toast('这篇日记仅保存，请先主动开启本篇分析。')}}
  if(legacy?.dataset.action==='correct-record'){const r=state.records.find(r=>r.id===state.activeRecord);if(!r?.aiConsent){event.stopImmediatePropagation();consentDialog(r,()=>correctRecord());return}}
  return
 }
 event.preventDefault();event.stopImmediatePropagation();if(b.disabled)return;const action=b.dataset.care||b.dataset.review,id=b.dataset.id,item=state.careItems.find(i=>i.id===id);
 if(action==='toggle'){state.careVisible=!state.careVisible;save();render();return}
 if(action==='add')return editCare();if(action==='edit')return editCare(id);if(action==='example')return editCare(null,b.dataset.name);
 if(action==='record')return careRecordDialog(id);
 if(action==='skip'){state.careEntries[state.day+'@'+id]={...state.careEntries[state.day+'@'+id],status:'skipped'};save();render();return}
 if(action==='move'){const i=state.careItems.findIndex(x=>x.id===id),j=i+Number(b.dataset.step);if(j>=0&&j<state.careItems.length)[state.careItems[i],state.careItems[j]]=[state.careItems[j],state.careItems[i]];save();render();return}
 if(action==='delete'){openDialog('移除这个关注项目？',`<p>${esc(item.name)}</p><p class="small muted">历史记录保留。首页不再出现它，晚间也不会机械追问这个项目。</p>`,()=>{state.ignoredCareTopics.push(item.topic);state.careItems=state.careItems.filter(i=>i.id!==id);save();closeDialog();render()},'确认移除');return}
 if(action==='suggest'){if(state.model.source==='off')return toast('AI 已关闭，你仍然可以自己添加项目。');$('#care-suggestions').innerHTML='<p class="quote">模拟建议：如果你最近常长时间看屏幕，可以考虑加一个“用眼休息”。你自己决定是否需要。</p><button class="btn compact" data-care="example" data-name="用眼休息">我想添加这项</button>';return}
 if(action==='enable-diary'){const r=diaryRecordCurrent();consentDialog(r,()=>analyzeDiary(r));return}
 if(action==='analyze-diary')return analyzeDiary(diaryRecordCurrent());
 if(action==='confirm-diary')return confirmDiary(diaryRecordCurrent());
 if(action==='confirm-event')return confirmEvent(state.records.find(r=>r.id===state.activeRecord));
 if(action==='separate-event'){const r=state.records.find(r=>r.id===state.activeRecord);r.relatedFact=null;r.forceSeparateFact=true;save();render();return}
 if(action==='separate-diary-fact'){const r=diaryRecordCurrent(),part=r.diaryAnalysis.items.find(i=>i.id===id),temp={text:part.text};suggestRecord(temp);part.kind=temp.suggestion?'new':'feedback';part.suggestion=temp.suggestion;part.factId=uid();part.forceSeparate=true;save();render();return}
},true);
document.addEventListener('change',e=>{if(e.target.id==='care-schedule')$('#care-weekdays').hidden=e.target.value!=='weekly'});
